BEGIN;
create temp table assertion_count(n int);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create function pg_temp.throws(statement text,label text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;perform pg_temp.check_it(failed,label);end$$;
create temp table st(k text primary key,v jsonb);
insert into public.organizations(id,name)values('ee640000-0000-4000-8000-000000000001','Account session SQL fixture');
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at)select ('ee640000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','session-'||n||'@fixture.invalid',clock_timestamp(),clock_timestamp(),clock_timestamp()from generate_series(101,103)n;
insert into public.profiles(id,org_id,role)select ('ee640000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=103 then null else'ee640000-0000-4000-8000-000000000001'::uuid end,case when n=102 then'admin'else'viewer'end from generate_series(101,103)n on conflict(id)do update set org_id=excluded.org_id,role=excluded.role;
insert into auth.sessions(id,user_id,created_at,updated_at,aal,user_agent)select ('ee640000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=204 then'ee640000-0000-4000-8000-000000000102'::uuid when n=205 then'ee640000-0000-4000-8000-000000000103'::uuid else'ee640000-0000-4000-8000-000000000101'::uuid end,clock_timestamp(),clock_timestamp(),'aal1','Private session device fixture'from generate_series(201,205)n;
create function pg_temp.read_sessions(b jsonb default'{}')returns jsonb language sql as $$select public.read_account_sessions('ee640000-0000-4000-8000-000000000101','ee640000-0000-4000-8000-000000000201','aal1',b)$$;
create function pg_temp.input(scope_value text default'others')returns jsonb language sql as $$select jsonb_build_object('scope',scope_value,'sourceHash',pg_temp.read_sessions()->>'sourceHash','confirmed',true)$$;
create function pg_temp.claim(i uuid,b jsonb)returns jsonb language sql as $$select public.claim_account_session(i,'ee640000-0000-4000-8000-000000000101','ee640000-0000-4000-8000-000000000201','aal1',b)$$;
create function pg_temp.review(i uuid,op text default'check')returns jsonb language sql as $$select public.review_account_session(i,'ee640000-0000-4000-8000-000000000101','ee640000-0000-4000-8000-000000000201',op)$$;
select pg_temp.check_it(jsonb_array_length(pg_temp.read_sessions()->'sessions')=3,'only own live sessions are returned');
select pg_temp.check_it(public.read_account_sessions('ee640000-0000-4000-8000-000000000101','ee640000-0000-4000-8000-000000000204','aal1')->>'state'='forbidden','another account session cannot authorize current owner');
select pg_temp.check_it(public.read_account_sessions('ee640000-0000-4000-8000-000000000103','ee640000-0000-4000-8000-000000000205','aal1')->>'state'='ready','unassigned account can use private security');
insert into st values('input',pg_temp.input()),('hash',to_jsonb(pg_temp.read_sessions()->>'sourceHash'));
update auth.sessions set refreshed_at=clock_timestamp(),user_agent='Updated private device'where id='ee640000-0000-4000-8000-000000000202';
select pg_temp.check_it(pg_temp.read_sessions()->'sourceHash'=(select v from st where k='hash'),'volatile refresh or device label does not invalidate reviewed identities');
insert into st values('claim',pg_temp.claim('ee640000-0000-4000-8000-000000000301',(select v from st where k='input')));
select pg_temp.check_it((select v->>'state'='claimed'and v->>'claimId'is not null from st where k='claim'),'first exact request receives one execution claim');
select pg_temp.check_it(pg_temp.claim('ee640000-0000-4000-8000-000000000301',(select v from st where k='input'))->>'state'='replayed'and not(pg_temp.claim('ee640000-0000-4000-8000-000000000301',(select v from st where k='input'))?'claimId'),'replay never returns execution capability');
select pg_temp.check_it(pg_temp.claim('ee640000-0000-4000-8000-000000000301',pg_temp.input('local'))->>'state'='request_conflict','changed reviewed scope cannot reuse identity');
select pg_temp.check_it(public.finish_account_session('ee640000-0000-4000-8000-000000000301','ee640000-0000-4000-8000-000000000101',gen_random_uuid(),'acknowledged')->>'state'='not_found','unowned claim cannot forge provider result');
select pg_temp.check_it(pg_temp.review('ee640000-0000-4000-8000-000000000301','cancel_unused')->>'status'='claimed','cancellation never undoes a started provider claim');
select pg_temp.check_it(pg_temp.review('ee640000-0000-4000-8000-000000000301')->'observation'->>'reviewedRemaining'='2','uncertain recovery truthfully observes still-present sessions');
delete from auth.sessions where id in('ee640000-0000-4000-8000-000000000202','ee640000-0000-4000-8000-000000000203');
select pg_temp.check_it(pg_temp.review('ee640000-0000-4000-8000-000000000301')->>'status'='observed','missing reviewed sessions become an observation');
select pg_temp.check_it(pg_temp.read_sessions('{"kind":"detail","requestId":"ee640000-0000-4000-8000-000000000301"}')->'providerResult'='null','observation does not fabricate provider acknowledgement');
select pg_temp.check_it(public.finish_account_session('ee640000-0000-4000-8000-000000000301','ee640000-0000-4000-8000-000000000101',(select(v->>'claimId')::uuid from st where k='claim'),'acknowledged')->>'status'='acknowledged','late actual provider receipt remains recordable after observation');
select pg_temp.check_it(public.finish_account_session('ee640000-0000-4000-8000-000000000301','ee640000-0000-4000-8000-000000000101',(select(v->>'claimId')::uuid from st where k='claim'),'uncertain')->>'state'='request_conflict','conflicting provider evidence cannot overwrite acknowledgement');
select pg_temp.check_it(public.read_account_sessions('ee640000-0000-4000-8000-000000000102','ee640000-0000-4000-8000-000000000204','aal1','{"kind":"detail","requestId":"ee640000-0000-4000-8000-000000000301"}')->>'state'='not_found','organization admin cannot read another member private history');
select pg_temp.check_it(pg_temp.review('ee640000-0000-4000-8000-000000000302','cancel_unused')->>'status'='cancelled','unused request cancellation persists');
select pg_temp.check_it(pg_temp.claim('ee640000-0000-4000-8000-000000000302',pg_temp.input('local'))->>'status'='cancelled','cancelled late request cannot acquire a provider claim');
select pg_temp.check_it(pg_temp.claim('ee640000-0000-4000-8000-000000000303',(select v from st where k='input'))->>'state'='sessions_changed','changed session membership holds old source');
select pg_temp.check_it(pg_temp.claim('ee640000-0000-4000-8000-000000000303',pg_temp.input())->>'state'='no_other_sessions','no phantom other-session action');
select pg_temp.throws($q$select pg_temp.claim('ee640000-0000-4000-8000-000000000303',pg_temp.input('local')||'{"token":"PRIVATE-TOKEN"}')$q$,'credentials cannot enter retained request');
select pg_temp.throws($q$delete from public.account_session_events where request_id='ee640000-0000-4000-8000-000000000301'$q$,'session evidence cannot be deleted');
select pg_temp.throws($q$update public.account_session_requests set scope='local'where id='ee640000-0000-4000-8000-000000000301'$q$,'session identity cannot be rewritten');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where org_id='ee640000-0000-4000-8000-000000000001'and(training_eligible or request::text like'%000000000201%'or result::text like'%Private%')),'shared summaries exclude device details and actual session identities');
update public.profiles set org_id=null where id='ee640000-0000-4000-8000-000000000101';
select pg_temp.check_it(pg_temp.read_sessions('{"kind":"detail","requestId":"ee640000-0000-4000-8000-000000000301"}')->>'state'='ready','private history survives membership loss');
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at)values('ee640000-0000-4000-8000-000000000801','ee640000-0000-4000-8000-000000000101','totp','verified',clock_timestamp(),clock_timestamp());
select pg_temp.check_it(pg_temp.read_sessions()->'canRevoke'='false','verified second factor holds low-assurance session mutations');
select pg_temp.check_it(pg_temp.claim('ee640000-0000-4000-8000-000000000303',pg_temp.input())->>'state'='mfa_required','native claim enforces second factor');
select pg_temp.check_it(public.claim_account_session('ee640000-0000-4000-8000-000000000303','ee640000-0000-4000-8000-000000000101','ee640000-0000-4000-8000-000000000201','aal1',pg_temp.input('local'))->>'state'='claimed','current-session sign-out remains available when another factor is required');
delete from auth.mfa_factors where id='ee640000-0000-4000-8000-000000000801';
select pg_temp.check_it(pg_temp.claim('ee640000-0000-4000-8000-000000000305',pg_temp.input('local'))->>'state'='existing_request','another current-session identity cannot acquire a concurrent provider claim');
create function pg_temp.fail_event()returns trigger language plpgsql as $$begin if new.actor_id='ee640000-0000-4000-8000-000000000101'then raise exception 'Fixture evidence failure';end if;return new;end$$;
create trigger session_fixture_evidence before insert on public.account_session_events for each row execute function pg_temp.fail_event();
select pg_temp.throws($q$select pg_temp.review('ee640000-0000-4000-8000-000000000304','cancel_unused')$q$,'failed event prevents provider claim');
drop trigger session_fixture_evidence on public.account_session_events;
select pg_temp.check_it(not exists(select 1 from public.account_session_requests where id='ee640000-0000-4000-8000-000000000304'),'failed recording leaves no partial request');
select pg_temp.check_it(not has_table_privilege('service_role','auth.sessions','SELECT')and not has_table_privilege('service_role','auth.users','SELECT'),'application does not receive broad auth access');
select pg_temp.check_it(not has_table_privilege('authenticated','public.account_session_requests','SELECT')and not has_function_privilege('authenticated','public.account_session_source(uuid,uuid)','EXECUTE'),'browser cannot invoke private session projection or read raw requests');
grant select,insert,update on assertion_count,st to service_role;
set local role service_role;
select pg_temp.check_it(pg_temp.read_sessions()->>'state'='ready','application role can read narrow session projection');
select pg_temp.check_it(pg_temp.review('ee640000-0000-4000-8000-000000000304','cancel_unused')->>'state'='saved','application role can record own session recovery');
reset role;
do $$declare n int;begin for n in 1001..2025 loop perform pg_temp.review(('ee640000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'cancel_unused');end loop;end$$;
insert into st values('history',pg_temp.read_sessions('{"kind":"history"}'));
select pg_temp.check_it((select v->>'total'='1029'from st where k='history'),'private history exceeds REST default row limit');
select pg_temp.check_it(jsonb_array_length(pg_temp.read_sessions(jsonb_build_object('kind','history','offset',1020,'expectedHash',(select v->>'pageHash'from st where k='history')))->'items')=9,'last page is reachable with exact history version');
select pg_temp.check_it(pg_temp.review('ee640000-0000-4000-8000-000000003001','cancel_unused')->>'state'='saved','new request appends after history review');
select pg_temp.check_it(pg_temp.read_sessions(jsonb_build_object('kind','history','offset',20,'expectedHash',(select v->>'pageHash'from st where k='history')))->>'state'='history_changed','new history invalidates older paging boundary');
delete from auth.sessions where id='ee640000-0000-4000-8000-000000000201';
select pg_temp.check_it(pg_temp.read_sessions()->>'state'='forbidden','revoked current session cannot use private security even with unexpired JWT');
select n as passed_assertions from assertion_count;
ROLLBACK;
